// node_modules tree metrics
// Đo số file, dung lượng và hardlink trong node_modules.
use crate::bench_matrix::*;

pub(in crate::bench_matrix) fn inspect_node_modules(
    root: &Path,
) -> anyhow::Result<NodeModulesStats> {
    if !root.exists() {
        return Ok(NodeModulesStats {
            files: 0,
            bytes: 0,
            hardlinked_files: 0,
        });
    }

    let mut files = 0usize;
    let mut bytes = 0u64;
    let mut hardlinked_files = 0usize;

    for entry in WalkDir::new(root).into_iter().filter_map(Result::ok) {
        if !entry.file_type().is_file() {
            continue;
        }
        files += 1;
        let metadata = entry.metadata()?;
        bytes += metadata.len();
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            if metadata.nlink() > 1 {
                hardlinked_files += 1;
            }
        }
    }

    Ok(NodeModulesStats {
        files,
        bytes,
        hardlinked_files,
    })
}
